	name: "normalOutput",
	outputs: { normal: "vec4<f32>" },
	gpu: { fragment: { end: `
  outputs.normal = vec4<f32>(normalize((camera.uViewMatrix * vec4<f32>(normal, 0.0)).xyz) * 0.5 + 0.5, 1.0);` } },
	gl: { fragment: { end: `
  outputs.normal = vec4(normalize((uViewMatrix * vec4(normal, 0.0)).xyz) * 0.5 + 0.5, 1.0);` } }
